<div class="patient-page-heading"><div><span class="eyebrow text-secondary">ORGANIZACIÓN DE LA ATENCIÓN</span><h1>Horarios médicos</h1><p class="text-secondary mb-0">Jornadas semanales y duración de consulta · America/La_Paz</p></div><?php if(\Clinica\Middleware\ScheduleAccess::schedules($user)): ?><a class="btn btn-clinic" href="/horarios/nuevo">+ Crear horario</a><?php endif; ?></div>
<?php require __DIR__.'/filters.php'; ?>
<p class="text-secondary" data-schedule-total="<?= count($catalog['hours']) ?>"><?= count($catalog['hours']) ?> horarios encontrados · <?= count($catalog['doctors']) ?> médicos en esta vista</p>
<?php foreach($catalog['doctors'] as $m): $hours=array_values(array_filter($catalog['hours'],static fn(array $h): bool=>(int)$h['id_medico']===(int)$m['id_medico'])); ?>
