<?php if(!$hours): ?><p class="p-4 mb-0 text-secondary">Sin horarios para estos filtros.</p><?php else: ?><div class="table-responsive"><table class="table patient-table mb-0"><caption class="visually-hidden">Horarios de <?= $escape($m['nombres']) ?></caption><thead><tr><th>Día</th><th>Atención</th><th>Duración</th><th>Estado</th><?php if(\Clinica\Middleware\ScheduleAccess::schedules($user)): ?><th>Acción</th><?php endif; ?></tr></thead><tbody><?php foreach($hours as $h): ?><tr data-schedule-id="<?= $escape($h['id_horario']) ?>"><td><?= \Clinica\Services\ScheduleValidator::DAYS[(int)$h['dia_semana']] ?></td><td><?= $escape($h['hora_inicio'].'–'.$h['hora_fin']) ?></td><td><?= $escape($h['duracion_cita_minutos']) ?> min</td><td><span class="status-chip <?= $h['estado']==='activo' ? 'is-active' : 'is-inactive' ?>"><?= $escape(ucfirst($h['estado'])) ?></span></td><?php if(\Clinica\Middleware\ScheduleAccess::schedules($user)): ?><td><a href="/horarios/editar?id=<?= $escape($h['id_horario']) ?>">Editar / desactivar</a></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endforeach; ?>
<?php if(!$catalog['doctors']): ?><div class="patient-empty">No hay médicos dentro de su ámbito para estos filtros.</div><?php endif; ?>

